#!/usr/bin/env python3
"""protein/esmfold_high_throughput — auto-generated run.py (archetype=structure_predict).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "structure_predict"
BRAIN = "protein"
SKILL = "esmfold_high_throughput"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'n_input': 10000, 'n_kept': 4500, 'n_review': 3000, 'n_discard': 2500, 'buckets_processed': [], 'throughput_seqs_per_hour': 1200, 'warnings': ['147 sequences > 1024 aa context window — chunked with loss of global context', '23 sequences detected NaN — fallback to fp32'], 'results_jsonl_path': 'results.jsonl', 'provenance': {}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """ESMFold v1 高通量单体预测。host_env=esmfold(fair-esm 2.0.0)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seqs = payload.get("sequences") or ([payload.get("sequence")] if payload.get("sequence") else [])
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="esmfold_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "predictor": "esmfold_v1", "n_sequences": len(seqs), "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "sequence": seqs[0] if seqs else "",
                "model_path": "", "plddt_mean": 0.0, "ptm": 0.0, "n_residues": 0,
                "runtime_sec": 0.0, "diagnostics": {**diagnostics, "dry": True}}
    if not seqs:
        return {"ok": False, "error": "需要 sequence 或 sequences", "diagnostics": diagnostics}
    script = (
        "import json, os, sys, torch\n"
        "import esm\n"
        f"seqs = {seqs!r}; out_dir = {out_dir!r}\n"
        "os.makedirs(out_dir, exist_ok=True)\n"
        "model = esm.pretrained.esmfold_v1().eval()\n"
        "if torch.cuda.is_available(): model = model.cuda()\n"
        "results = []\n"
        "for i, s in enumerate(seqs):\n"
        "    with torch.no_grad():\n"
        "        out = model.infer_pdb(s)\n"
        "    p = os.path.join(out_dir, f'pred_{i:03d}.pdb')\n"
        "    with open(p, 'w') as fh: fh.write(out)\n"
        "    # 简单解析 pLDDT(取 B-factor 平均)\n"
        "    bfacs = []\n"
        "    for ln in out.splitlines():\n"
        "        if ln.startswith('ATOM') and len(ln) >= 66:\n"
        "            try: bfacs.append(float(ln[60:66].strip()))\n"
        "            except: pass\n"
        "    plddt = sum(bfacs)/len(bfacs) if bfacs else 0.0\n"
        "    results.append({'idx': i, 'sequence': s, 'model_path': p, 'plddt_mean': plddt, 'n_residues': len(s)})\n"
        "json.dump({'results': results}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ESMFold 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    first = (parsed.get("results") or [{}])[0]
    return {"ok": True, "skill_id": SKILL,
            "sequence": first.get("sequence", ""),
            "model_path": first.get("model_path", ""),
            "plddt_mean": first.get("plddt_mean", 0.0),
            "ptm": 0.0, "n_residues": first.get("n_residues", 0),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "all_results": parsed.get("results")}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
